import{_ as r,C as d,o as s,c,j as t,a,E as n,a2 as i}from"./chunks/framework.BEactgC_.js";const b=JSON.parse('{"title":"Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"reference/architecture.md","filePath":"reference/architecture.md","lastUpdated":1794409413000}'),l={name:"reference/architecture.md"};function h(p,e,u,k,m,f){const o=d("ArchitectureDiagram");return s(),c("div",null,[e[0]||(e[0]=t("h1",{id:"architecture",tabindex:"-1"},[a("Architecture "),t("a",{class:"header-anchor",href:"#architecture","aria-label":'Permalink to "Architecture"'},"​")],-1)),e[1]||(e[1]=t("p",null,[a("How a SvelteKit build ends up in the JAR, and how a request reaches a file. Read this before changing the plugin or the runtime. "),t("a",{href:"./how-it-works"},"How it works"),a(" has the exact resolution rules.")],-1)),n(o),e[2]||(e[2]=i('<h2 id="build-time" tabindex="-1">Build time <a class="header-anchor" href="#build-time" aria-label="Permalink to &quot;Build time&quot;">​</a></h2><p>The Gradle plugin turns the frontend into resources of your app. Each step is a cacheable task, wired before <code>processResources</code>:</p><table tabindex="0"><thead><tr><th>Step</th><th>What it does</th><th>Source</th></tr></thead><tbody><tr><td><code>svelteInstall</code></td><td>Installs dependencies from the lockfile with the detected package manager</td><td><code>tasks/SvelteTasks.kt</code>, <code>PackageManager.kt</code></td></tr><tr><td><code>svelteBuild</code></td><td>Runs the build script. Its inputs include a fingerprint of the package manager</td><td><code>tasks/SvelteTasks.kt</code>, <code>tasks/ToolFingerprint.kt</code></td></tr><tr><td><code>svelteBundle</code></td><td>Copies the output to <code>ktor-svelte/public/</code>, gzips what the adapter did not compress, hashes inline scripts and writes <code>ktor-svelte/manifest.json</code></td><td><code>tasks/SvelteBundleTask.kt</code>, <code>tasks/InlineScripts.kt</code></td></tr><tr><td><code>svelteSync</code></td><td>Writes the frontend library setup and generated files from <code>svelte { libraries { } }</code></td><td><code>tasks/SvelteSyncTasks.kt</code>, <code>libraries/</code></td></tr></tbody></table><p>Paths are relative to <code>ktor-svelte-gradle-plugin/src/main/kotlin/io/github/nijasc/ktor/svelte/gradle/</code>.</p><p>The manifest is the contract between the two halves. It lists every servable file with its size, hash, precompressed variants and, for HTML pages, the hashes of their inline scripts. The runtime never turns a request path into a file path. It only looks paths up in the manifest.</p><h2 id="request-time" tabindex="-1">Request time <a class="header-anchor" href="#request-time" aria-label="Permalink to &quot;Request time&quot;">​</a></h2><p><code>install(Svelte)</code> adds a catch-all route and a few hooks. Ktor prefers more specific routes, so your own routes always win.</p><table tabindex="0"><thead><tr><th>Step</th><th>What it does</th><th>Source</th></tr></thead><tbody><tr><td>Guards</td><td>Origin check, body size, JSON shape limits and rate limits on API paths</td><td><code>internal/security/RequestGuards.kt</code>, <code>JsonShapeLimits.kt</code>, <code>RateLimits.kt</code></td></tr><tr><td>Catch-all</td><td>Takes GET and HEAD requests that no route of yours answered, and answers 405 for other methods on known pages</td><td><code>internal/SvelteHandler.kt</code></td></tr><tr><td>Resolution</td><td>Maps the path to a manifest entry, a 308 redirect, the SPA fallback or a 404</td><td><code>internal/assets/RequestResolver.kt</code></td></tr><tr><td>Response</td><td>Sets <code>Cache-Control</code>, <code>ETag</code> and CSP, picks a precompressed variant, serves byte ranges and injects <code>publicConfig</code></td><td><code>internal/assets/AssetResponder.kt</code>, <code>ByteRanges.kt</code>, <code>ConfigInjector.kt</code></td></tr><tr><td>Storage</td><td>Opens files from the classpath or from <code>SvelteSource.Directory</code></td><td><code>internal/assets/AssetStore.kt</code>, <code>Manifest.kt</code></td></tr></tbody></table><p>Paths are relative to <code>ktor-svelte-server/src/main/kotlin/io/github/nijasc/ktor/svelte/</code>. The root package holds only the public API, such as <code>Svelte.kt</code> and <code>SvelteConfig.kt</code>.</p><h2 id="development" tabindex="-1">Development <a class="header-anchor" href="#development" aria-label="Permalink to &quot;Development&quot;">​</a></h2><p>In development mode the same catch-all sends frontend requests to Vite through <code>internal/dev/DevProxy.kt</code>, which uses the JDK <code>HttpClient</code> and only serves local clients. Your API routes still answer directly, so the browser talks to one origin.</p><p><code>generateTs</code> reads Ktor&#39;s OpenAPI model of your routes when the app starts and writes the TypeScript client. That code lives in <code>internal/typescript/</code>, and the client templates are TypeScript files under <code>src/main/resources</code>. The development-only endpoints, such as the route table and the status page, are in <code>internal/dev/</code>.</p><p><code>svelteDevAll</code> starts Vite and the app together, waits until both answer, and prints one ready banner. See <code>tasks/SvelteDevAllTask.kt</code> and <code>tasks/ReadyBanner.kt</code>.</p>',13))])}const g=r(l,[["render",h]]);export{b as __pageData,g as default};
